  1→import { useCallback, useEffect, useRef, useState } from 'react';
  2→import { useNavigate } from 'react-router-dom';
  3→import { useCoreKitAuth } from '../lib/web3auth/hooks';
  4→import { useCoreKit } from '../lib/web3auth/core-kit-provider';
  5→import { authApi } from '../lib/api/auth';
  6→import { vaultApi } from '../lib/api/vault';
  7→import { useAuthStore } from '../stores/auth.store';
  8→import { useFolderStore } from '../stores/folder.store';
  9→import { useVaultStore } from '../stores/vault.store';
 10→import { useDeviceRegistryStore } from '../stores/device-registry.store';
 11→import { clearAllUserStores } from '../lib/clear-user-stores';
 12→import { initSdkClient } from '../lib/sdk-provider';
 13→// api-config.ts handles setApiClientConfig at module load time
 14→import { initializeVault, encryptVaultKeys, decryptVaultKeys } from '@cipherbox/core';
 15→import { deriveIpnsName, hexToBytes, bytesToHex } from '@cipherbox/crypto';
 16→import { getOrCreateDeviceIdentity } from '../lib/device/identity';
 17→import { detectDeviceInfo } from '../lib/device/info';
 18→import { initializeOrSyncRegistry } from '../services/device-registry.service';
 19→import { initializeBin } from '../services/bin.service';
 20→import { useBinStore } from '../stores/bin.store';
 21→import { vaultControllerGetConfig } from '@cipherbox/api-client';
 22→
 23→export function useAuth() {
 24→  const navigate = useNavigate();
 25→  const {
 26→    isLoggedIn: coreKitLoggedIn,
 27→    isInitialized: coreKitInitialized,
 28→    isRequiredShare,
 29→    loginWithGoogle: coreKitLoginGoogle,
 30→    loginWithEmailOtp: coreKitLoginEmail,
 31→    loginWithWallet: coreKitLoginWallet,
 32→    getVaultKeypair,
 33→    getPublicKeyHex,
 34→    logout: coreKitLogout,
 35→  } = useCoreKitAuth();
 36→  const { syncStatus } = useCoreKit();
 37→  const {
 38→    accessToken,
 39→    isAuthenticated,
 40→    lastAuthMethod,
 41→    userEmail,
 42→    setAccessToken,
 43→    setAuthenticated,
 44→    setLastAuthMethod,
 45→    setUserEmail,
 46→    setVaultKeypair,
 47→  } = useAuthStore();
 48→
 49→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 50→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 51→  const restoringRef = useRef(false);
 52→
 53→  // Stable refs for functions used in the session restoration effect.
 54→  // This prevents the effect from re-firing when function references change.
 55→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 56→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 57→
 58→  // Pending auth state for REQUIRED_SHARE flow.
 59→  // Stored in Zustand (not useState) so the state is shared across all
 60→  // useAuth() hook instances — Login.tsx sets it, useDeviceApproval reads it
 61→  // via its own useAuth() call.
 62→  const pendingAuthMethod = useAuthStore((s) => s.pendingAuthMethod);
 63→  const setPendingAuth = useAuthStore((s) => s.setPendingAuth);
 64→
 65→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 66→
 67→  // Get vault store actions
 68→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 69→
 70→  /**
 71→   * Initialize vault for new users or load existing vault keys.
 72→   * Called after successful backend authentication.
 73→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 74→   */
 75→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 76→    // Get user's secp256k1 keypair from Core Kit TSS export
 77→    const userKeypair = await getVaultKeypair();
 78→
 79→    if (!userKeypair) {
 80→      throw new Error('Failed to get vault keypair from Core Kit');
 81→    }
 82→
 83→    // Store keypair in auth store for crypto operations
 84→    setVaultKeypair(userKeypair);
 85→
 86→    try {
 87→      // Try to fetch existing vault
 88→      const existingVault = await vaultApi.getVault();
 89→
 90→      // Store TEE keys if available
 91→      if (existingVault.teeKeys) {
 92→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
 93→      }
 94→
 95→      // Vault exists - decrypt keys and load into store
 96→      // decryptVaultKeys derives the IPNS public key internally from the decrypted private key
 97→      const decryptedVault = await decryptVaultKeys(
 98→        {
 99→          encryptedRootFolderKey: hexToBytes(existingVault.encryptedRootFolderKey),
100→          encryptedIpnsPrivateKey: hexToBytes(existingVault.encryptedRootIpnsPrivateKey),
101→        },
102→        userKeypair.privateKey
103→      );
104→
105→      setVaultKeys({
106→        rootFolderKey: decryptedVault.rootFolderKey,
107→        rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
108→        rootIpnsName: existingVault.rootIpnsName,
109→        vaultId: existingVault.id,
110→      });
111→    } catch (error) {
112→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
113→
114→      if (is404) {
115→        // New user - initialize vault
116→        console.log(
117→          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
118→        );
119→        const newVault = await initializeVault(userKeypair.privateKey);
120→        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
121→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
122→
123→        const storedVault = await vaultApi.initVault({
124→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
125→          encryptedRootFolderKey: bytesToHex(encryptedVault.encryptedRootFolderKey),
126→          encryptedRootIpnsPrivateKey: bytesToHex(encryptedVault.encryptedIpnsPrivateKey),
127→          rootIpnsName,
128→        });
129→
130→        if (storedVault.teeKeys) {
131→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
132→        }
133→
134→        setVaultKeys({
135→          rootFolderKey: newVault.rootFolderKey,
136→          rootIpnsKeypair: newVault.rootIpnsKeypair,
137→          rootIpnsName,
138→          vaultId: storedVault.id,
139→          isNewVault: true,
140→        });
141→      } else {
142→        console.error('[useAuth] Failed to load vault:', error);
143→        throw error;
144→      }
145→    }
146→
147→    // Initialize SDK client with decrypted vault keys
148→    const vaultState = useVaultStore.getState();
149→    const authState = useAuthStore.getState();
150→    if (vaultState.rootFolderKey && vaultState.rootIpnsKeypair && vaultState.rootIpnsName) {
151→      const apiUrl = import.meta.env.VITE_API_URL || window.location.origin + '/api';
152→      const getAccessToken = async () => {
153→        const state = useAuthStore.getState();
154→        return state.accessToken || '';
155→      };
156→
157→      // @cipherbox/api-client is configured in lib/api-config.ts at module load time.
158→
159→      const sdkClient = initSdkClient({
160→        apiUrl,
161→        getAccessToken,
162→        vaultKeypair: {
163→          publicKey: userKeypair.publicKey,
164→          privateKey: userKeypair.privateKey,
165→        },
166→        rootIpnsName: vaultState.rootIpnsName,
167→        rootFolderKey: vaultState.rootFolderKey,
168→        teeKeys: authState.teeKeys ?? undefined,
169→        shareCallbacks: {
170→          getCoveringShares: async (folderIpnsName: string) => {
171→            const { findCoveringShares } = await import('../services/share.service');
172→            const folders = useFolderStore.getState().folders;
173→            // Find the folder ID from IPNS name for ancestor traversal
174→            const folderId =
175→              Object.keys(folders).find((id) => folders[id].ipnsName === folderIpnsName) ?? null;
176→            return findCoveringShares(folderIpnsName, folders, folderId);
177→          },
178→          addShareKeys: async (shareId, keys) => {
179→            const { addShareKeys } = await import('../services/share.service');
180→            await addShareKeys(shareId, keys);
181→          },
182→        },
183→      });
184→
185→      // Subscribe folder store to SDK events
186→      useFolderStore.getState().subscribeToSdk(sdkClient);
187→
188→      // Subscribe bin store to SDK events
189→      useBinStore.getState().subscribeToSdk(sdkClient);
190→    }
191→
192→    // Non-blocking device registry initialization (fire-and-forget)
193→    // Placed after vault load so registry failures never block login
194→    void (async () => {
195→      try {
196→        const deviceKeypair = await getOrCreateDeviceIdentity({
197→          mode: 'persisted',
198→          vaultPrivateKey: userKeypair.privateKey,
199→        });
200→        const deviceInfo = detectDeviceInfo();
201→        const result = await initializeOrSyncRegistry({
202→          userPrivateKey: userKeypair.privateKey,
203→          userPublicKey: userKeypair.publicKey,
204→          deviceKeypair,
205→          deviceInfo: { ...deviceInfo, ipHash: '' },
206→        });
207→        if (result) {
208→          useDeviceRegistryStore
209→            .getState()
210→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
211→        }
212→      } catch (error) {
213→        console.error('[Auth] Device registry init failed (non-blocking):', error);
214→      }
215→    })();
216→
217→    // Non-blocking bin initialization (fire-and-forget)
218→    // After old service creates/loads bin, also load into SDK for deleteToBin support
219→    void (async () => {
220→      try {
221→        await initializeBin({
222→          userPrivateKey: userKeypair.privateKey,
223→          userPublicKey: userKeypair.publicKey,
224→        });
225→        // Now load bin into SDK (old service ensures bin IPNS record exists)
226→        const { getSdkClient, hasSdkClient } = await import('../lib/sdk-provider');
227→        if (hasSdkClient()) {
228→          await getSdkClient().loadBin();
229→        }
230→      } catch (error) {
231→        console.error('[Auth] Bin initialization failed (non-blocking):', error);
232→      }
233→    })();
234→
235→    // Non-blocking: fetch retention config from API
236→    void (async () => {
237→      try {
238→        const config = await vaultControllerGetConfig();
239→        if (config.recycleBinRetentionDays != null) {
240→          useBinStore.getState().setRetentionDays(config.recycleBinRetentionDays);
241→        }
242→      } catch (error) {
243→        console.error('[Auth] Failed to fetch vault config (non-blocking):', error);
244→      }
245→    })();
246→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
247→
248→  /**
249→   * Complete backend authentication after Core Kit login.
250→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
251→   * to the backend with loginType 'corekit'. The backend verifies it against
252→   * its own JWKS since CipherBox is the identity provider.
253→   */
254→  const completeBackendAuth = useCallback(
255→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
256→      // 1. Get real publicKey from Core Kit TSS export
257→      const publicKey = await getPublicKeyHex();
258→      if (!publicKey) {
259→        throw new Error('Failed to get publicKey from Core Kit');
260→      }
261→
262→      // publicKey available for debugging via DevTools if needed
263→
264→      // 2. Authenticate with CipherBox backend
265→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
266→      const response = await authApi.login({
267→        idToken: cipherboxJwt,
268→        publicKey,
269→        loginType: 'corekit',
270→      });
271→
272→      // 3. Store access token (refresh token in HTTP-only cookie)
273→      // Note: this does NOT set isAuthenticated — we wait until vault + SDK
274→      // are fully initialized to prevent Login.tsx from redirecting to /files
275→      // before the SDK client is ready for file operations.
276→      setAccessToken(response.accessToken);
277→
278→      // 4. Remember auth method for UX
279→      setLastAuthMethod(authMethod);
280→
281→      // 5. Initialize or load vault + SDK client
282→      await initializeOrLoadVault();
283→
284→      // 6. Now that vault keys are loaded and SDK is initialized,
285→      // mark the user as authenticated. This triggers Login.tsx → /files redirect.
286→      setAuthenticated();
287→    },
288→    [getPublicKeyHex, setAccessToken, setAuthenticated, setLastAuthMethod, initializeOrLoadVault]
289→  );
290→
291→  /**
292→   * Complete the login flow after REQUIRED_SHARE is resolved.
293→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
294→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
295→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
296→   */
297→  const completeRequiredShare = useCallback(async (): Promise<void> => {
298→    // Read directly from Zustand store to get fresh values — this callback
299→    // may be called from useDeviceApproval's useAuth() instance, so we
300→    // can't rely on closure-captured selector values.
301→    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();
302→
303→    if (!jwt || !method) {
304→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
305→    }
306→
307→    // Core Kit should now be LOGGED_IN after inputFactorKey()
308→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
309→    await completeBackendAuth(method, jwt);
310→
311→    // NOW sync Core Kit React state to LOGGED_IN.
312→    // We deliberately delayed this from inputFactorKey() to prevent the session
313→    // restoration effect from firing before backend auth completed.
314→    // At this point isAuthenticated is true (from completeBackendAuth -> setAuthenticated),
315→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
316→    syncStatus();
317→
318→    // Clear pending state
319→    setPendingAuth(null, null);
320→
321→    // Navigate to files
322→    navigate('/files');
323→  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);
324→
325→  /**
326→   * Login with Google OAuth token.
327→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
328→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
329→   */
330→  const loginWithGoogle = useCallback(
331→    async (googleIdToken: string): Promise<void> => {
332→      if (isLoggingIn) return;
333→      setIsLoggingIn(true);
334→      try {
335→        // 1. Core Kit login via CipherBox identity provider
336→        const {
337→          cipherboxJwt,
338→          email,
339→          userId,
340→          status: coreKitStatus,
341→        } = await coreKitLoginGoogle(googleIdToken);
342→
343→        if (coreKitStatus === 'required_share') {
344→          // MFA enabled but device factor missing.
345→          // Store pending auth info for later completion after factor input.
346→          setPendingAuth(cipherboxJwt, 'google');
347→
348→          // Obtain temporary backend access token so the new device can
349→          // call bulletin board API endpoints (device-approval/*).
350→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
351→          // state and we can't export the TSS key yet.
352→          const tempLoginResponse = await authApi.login({
353→            idToken: cipherboxJwt,
354→            publicKey: `pending-core-kit-${userId}`,
355→            loginType: 'corekit',
356→          });
357→          setAccessToken(tempLoginResponse.accessToken);
358→
359→          if (email) {
360→            setUserEmail(email);
361→          }
362→
363→          // Do NOT call completeBackendAuth() or navigate('/files')
364→          // The component tree will see isRequiredShare === true and
365→          // render recovery/approval UI.
366→          return;
367→        }
368→
369→        // Normal path: Core Kit logged in, proceed as before
370→        // 2. Complete backend auth + vault init
371→        await completeBackendAuth('google', cipherboxJwt);
372→
373→        // 3. Store email for UI display (returned from identity endpoint)
374→        if (email) {
375→          setUserEmail(email);
376→        }
377→
378→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
379→      } catch (error) {
380→        console.error('[useAuth] Google login failed:', error);
381→        throw error;
382→      } finally {
383→        setIsLoggingIn(false);
384→      }
385→    },
386→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
387→  );
388→
389→  /**
390→   * Login with Email OTP.
391→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
392→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
393→   */
394→  const loginWithEmail = useCallback(
395→    async (email: string, otp: string): Promise<void> => {
396→      if (isLoggingIn) return;
397→      setIsLoggingIn(true);
398→      try {
399→        // 1. Core Kit login via CipherBox identity provider
400→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
401→
402→        if (coreKitStatus === 'required_share') {
403→          setPendingAuth(cipherboxJwt, 'email');
404→
405→          const tempLoginResponse = await authApi.login({
406→            idToken: cipherboxJwt,
407→            publicKey: `pending-core-kit-${userId}`,
408→            loginType: 'corekit',
409→          });
410→          setAccessToken(tempLoginResponse.accessToken);
411→          setUserEmail(email);
412→          return;
413→        }
414→
415→        // Normal path
416→        await completeBackendAuth('email', cipherboxJwt);
417→        setUserEmail(email);
418→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
419→      } catch (error) {
420→        console.error('[useAuth] Email login failed:', error);
421→        throw error;
422→      } finally {
423→        setIsLoggingIn(false);
424→      }
425→    },
426→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
427→  );
428→
429→  /**
430→   * Login with Wallet (SIWE).
431→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
432→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
433→   */
434→  const loginWithWallet = useCallback(
435→    async (cipherboxJwt: string, userId: string): Promise<void> => {
436→      if (isLoggingIn) return;
437→      setIsLoggingIn(true);
438→      try {
439→        // 1. Core Kit login via CipherBox identity provider
440→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
441→
442→        if (coreKitStatus === 'required_share') {
443→          setPendingAuth(cipherboxJwt, 'wallet');
444→
445→          const tempLoginResponse = await authApi.login({
446→            idToken: cipherboxJwt,
447→            publicKey: `pending-core-kit-${userId}`,
448→            loginType: 'corekit',
449→          });
450→          setAccessToken(tempLoginResponse.accessToken);
451→          return;
452→        }
453→
454→        // Normal path
455→        await completeBackendAuth('wallet', cipherboxJwt);
456→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
457→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
458→        // inside it may still be pending. An explicit navigate here would fire AFTER
459→        // vault init completes — by which point the user may have navigated away from
460→        // the login page, causing a disruptive late redirect.
461→      } catch (error) {
462→        console.error('[useAuth] Wallet login failed:', error);
463→        throw error;
464→      } finally {
465→        setIsLoggingIn(false);
466→      }
467→    },
468→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
469→  );
470→
471→  // Complete logout: Backend -> Core Kit -> Clear state
472→  const logout = useCallback(async () => {
473→    if (isLoggingOut) return;
474→
475→    setIsLoggingOut(true);
476→    try {
477→      // 1. Call backend logout (clears cookie)
478→      if (accessToken) {
479→        try {
480→          await authApi.logout();
481→        } catch {
482→          // Ignore errors -- we'll clear state anyway
483→        }
484→      }
485→
486→      // 2. Logout Core Kit (clears session from localStorage)
487→      await coreKitLogout();
488→
489→      // 3. Clear all user-scoped stores (centralized helper)
490→      clearAllUserStores();
491→
492→      // 4. Navigate to login
493→      navigate('/');
494→    } catch (error) {
495→      console.error('[useAuth] Logout failed:', error);
496→      // Still clear state even if backend fails
497→      clearAllUserStores();
498→      navigate('/');
499→    } finally {
500→      setIsLoggingOut(false);
501→    }
502→  }, [accessToken, coreKitLogout, navigate, isLoggingOut]);
503→
504→  // Keep function refs up-to-date for use in session restoration effect.
505→  // Using refs prevents the effect from re-firing when function identities change.
506→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
507→  coreKitLogoutRef.current = coreKitLogout;
508→
509→  // Session restoration: if Core Kit restores a session from localStorage
510→  // on init, we have LOGGED_IN status without going through login flow.
511→  // Complete backend auth + vault loading.
512→  useEffect(() => {
513→    const restoreSession = async () => {
514→      // Only restore if Core Kit has a session but we don't have
515→      // a backend access token yet
516→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
517→        restoringRef.current = true;
518→        setIsLoggingIn(true);
519→        try {
520→          // Try to refresh using the HTTP-only cookie first
521→          const response = await authApi.refresh();
522→          setAccessToken(response.accessToken);
523→
524→          // Restore email from backend if available
525→          if (response.email) {
526→            setUserEmail(response.email);
527→          }
528→
529→          // Load vault keys from Core Kit keypair + initialize SDK
530→          await initializeOrLoadVaultRef.current?.();
531→
532→          // Mark as authenticated only after vault + SDK are ready
533→          setAuthenticated();
534→        } catch {
535→          // No valid backend session -- user needs to re-login
536→          // Core Kit session exists but backend cookie expired
537→          // Clear Core Kit session to avoid inconsistent state
538→          try {
539→            await coreKitLogoutRef.current?.();
540→          } catch {
541→            // Ignore logout errors during cleanup
542→          }
543→        } finally {
544→          restoringRef.current = false;
545→          setIsLoggingIn(false);
546→        }
547→      }
548→    };
549→    restoreSession();
550→  }, [
551→    coreKitLoggedIn,
552→    isAuthenticated,
553→    isLoggingIn,
554→    setAccessToken,
555→    setAuthenticated,
556→    setUserEmail,
557→  ]);
558→
559→  return {
560→    isLoading,
561→    isAuthenticated,
562→    isRequiredShare,
563→    lastAuthMethod,
564→    userEmail,
565→    pendingAuthMethod,
566→    loginWithGoogle,
567→    loginWithEmail,
568→    loginWithWallet,
569→    completeRequiredShare,
570→    logout,
571→  };
572→}
