178→
179→// ---------------------------------------------------------------------------
180→// Post-upload / post-create share key propagation
181→// ---------------------------------------------------------------------------
182→
183→/**
184→ * Ensure sent shares cache is fresh (fetched within last 30s).
185→ * Returns the current sent shares array.
186→ */
187→async function ensureFreshSentShares(): Promise<SentShare[]> {
188→  const store = useShareStore.getState();
189→  if (store.lastSentFetchedAt && Date.now() - store.lastSentFetchedAt < 30_000) {
190→    return store.sentShares;
191→  }
192→  // Re-wrapping needs the full set — paginate through all pages
193→  const allShares = await fetchAllSentShares();
194→  useShareStore.getState().setSentShares(allShares);
195→  return allShares;
196→}
197→
198→/**
199→ * Fetch ALL sent shares by paginating through the API.
200→ * The API enforces a max limit of 100 per page.
201→ */
202→async function fetchAllSentShares(): Promise<SentShare[]> {
203→  const pageSize = 100;
204→  let offset = 0;
205→  const allShares: SentShare[] = [];
206→
207→  while (true) {
208→    const { shares, total } = await fetchSentShares(pageSize, offset);
209→    allShares.push(...shares);
210→    offset += shares.length;
211→    if (offset >= total || shares.length === 0) break;
212→  }
213→
214→  return allShares;
215→}
216→
217→/**
218→ * Check if a folder (by IPNS name) has any active shares.
219→ * Used to decide whether post-upload re-wrapping is needed.
220→ */
221→export async function hasActiveShares(folderIpnsName: string): Promise<boolean> {
222→  const shares = await ensureFreshSentShares();
223→  return shares.some((s) => s.ipnsName === folderIpnsName);
224→}
225→
226→/**
227→ * Find active shares that cover a given folder, including ancestor shares.
228→ * A folder is "covered" if it or any of its ancestor folders is shared.
229→ *
230→ * Walks the ancestor chain and checks each folder's IPNS name against sent shares.
231→ *
232→ * @param folderIpnsName - IPNS name of the current folder
233→ * @param folders - Current folder tree from the folder store
234→ * @param currentFolderId - ID of the current folder in the tree
235→ * @returns Array of sent shares covering this folder (may be from ancestor)
236→ */
237→export async function findCoveringShares(
238→  folderIpnsName: string,
239→  folders: Record<string, FolderNode>,
240→  currentFolderId: string | null
241→): Promise<SentShare[]> {
242→  const shares = await ensureFreshSentShares();
243→  if (shares.length === 0) return [];
244→
245→  // Collect all IPNS names from this folder up to root
246→  const ipnsNames = new Set<string>();
247→  ipnsNames.add(folderIpnsName);
248→
249→  let walkId = currentFolderId;
250→  while (walkId) {
251→    const node = folders[walkId];
252→    if (!node) break;
253→    ipnsNames.add(node.ipnsName);
254→    walkId = node.parentId;
255→  }
256→
257→  return shares.filter((s) => ipnsNames.has(s.ipnsName));
258→}
259→
260→/**
261→ * After adding a file or subfolder to a shared folder, re-wrap the new key
262→ * for all existing share recipients.
263→ *
264→ * This is a fire-and-forget operation -- failures are logged but don't block
265→ * the primary upload/create flow.
266→ *
267→ * IMPORTANT: Callers are responsible for zeroing `newItems[*].plaintextKey`
268→ * after this function completes. This function does NOT zero the keys because
269→ * some callers (e.g., subfolder creation) keep the key alive in the store.
270→ * Use a `finally` block to ensure zeroing even on errors.
271→ *
272→ * @param params.folderIpnsName - IPNS name of the folder being modified
273→ * @param params.folders - Current folder tree from the store
274→ * @param params.currentFolderId - ID of the current folder in the tree
275→ * @param params.newItems - New items whose keys need re-wrapping
276→ */
277→export async function reWrapForRecipients(params: {
278→  folderIpnsName: string;
279→  folders: Record<string, FolderNode>;
280→  currentFolderId: string | null;
281→  newItems: Array<{
282→    keyType: 'file' | 'folder';
283→    itemId: string;
284→    plaintextKey: Uint8Array;
285→  }>;
286→}): Promise<{ failedRecipients: string[] }> {
287→  const coveringShares = await findCoveringShares(
288→    params.folderIpnsName,
289→    params.folders,
290→    params.currentFolderId
291→  );
292→
293→  if (coveringShares.length === 0) return { failedRecipients: [] };
294→
295→  const failedRecipients: string[] = [];
296→
297→  // For each share recipient, re-wrap all new item keys
298→  for (const share of coveringShares) {
299→    try {
300→      const recipientPubKey = hexToBytes(
301→        share.recipientPublicKey.startsWith('0x')
302→          ? share.recipientPublicKey.slice(2)
303→          : share.recipientPublicKey
304→      );
305→
306→      const wrappedKeys: Array<{
307→        keyType: 'file' | 'folder';
308→        itemId: string;
309→        encryptedKey: string;
310→      }> = [];
311→
312→      for (const item of params.newItems) {
313→        const wrapped = await wrapKey(item.plaintextKey, recipientPubKey);
314→        wrappedKeys.push({
315→          keyType: item.keyType,
316→          itemId: item.itemId,
317→          encryptedKey: bytesToHex(wrapped),
318→        });
319→      }
320→
321→      // Add the wrapped keys to this share via API
322→      await addShareKeys(share.shareId, wrappedKeys);
323→    } catch (err) {
324→      console.warn(
325→        `[share] Failed to re-wrap keys for recipient ${share.recipientPublicKey.slice(0, 10)}...:`,
326→        err
327→      );
328→      failedRecipients.push(share.recipientPublicKey);
329→    }
330→  }
331→
332→  return { failedRecipients };
333→}
