  1→/**
  2→ * Invite Service - Frontend invite link creation and claim with ephemeral key bridge
  3→ *
  4→ * Core security pattern: The sharer generates an ephemeral secp256k1 keypair,
  5→ * wraps the item key with the ephemeral public key, and puts the ephemeral
  6→ * PRIVATE key in the URL fragment (never sent to server). The recipient
  7→ * unwraps with the ephemeral private key and re-wraps with their own public key.
  8→ *
  9→ * All ephemeral and plaintext key material is zeroed in finally blocks.
 10→ */
 11→
 12→import * as secp256k1 from '@noble/secp256k1';
 13→import { wrapKey, unwrapKey, hexToBytes, bytesToHex } from '@cipherbox/crypto';
 14→import type { FolderChild, FolderEntry, FilePointer } from '@cipherbox/core';
 15→import { useAuthStore } from '../stores/auth.store';
 16→import {
 17→  invitesControllerGetInviteStatus,
 18→  invitesControllerGetInviteData,
 19→  invitesControllerClaimInvite,
 20→  shareInvitesControllerCreateInvite,
 21→  shareInvitesControllerListInvites,
 22→  shareInvitesControllerRevokeInvite,
 23→} from '@cipherbox/api-client';
 24→import { collectChildKeys } from '../lib/crypto/key-wrapping';
 25→import { resolveFileMetadata } from './file-metadata.service';
 26→import { resolveIpnsRecord } from './ipns.service';
 27→import { fetchFromIpfs } from '../lib/api/ipfs';
 28→import { decryptFolderMetadata } from '@cipherbox/core';
 29→
 30→// ---------------------------------------------------------------------------
 31→// Types
 32→// ---------------------------------------------------------------------------
 33→
 34→/** Info about an active invite link */
 35→export type InviteInfo = {
 36→  id: string;
 37→  token: string;
 38→  status: string;
 39→  itemType: string;
 40→  ipnsName: string;
 41→  itemName: string;
 42→  expiresAt: string;
 43→  createdAt: string;
 44→};
 45→
 46→// ---------------------------------------------------------------------------
 47→// Ephemeral keypair generation
 48→// ---------------------------------------------------------------------------
 49→
 50→/**
 51→ * Generate an ephemeral secp256k1 keypair for invite link creation.
 52→ * The private key goes in the URL fragment (never sent to server).
 53→ * The public key wraps the item key (stored on server as ciphertext).
 54→ */
 55→function generateEphemeralKeypair(): {
 56→  privateKey: Uint8Array;
 57→  publicKey: Uint8Array;
 58→  privateKeyHex: string;
 59→} {
 60→  const keypair = secp256k1.keygen();
 61→  return {
 62→    privateKey: keypair.secretKey,
 63→    publicKey: secp256k1.getPublicKey(keypair.secretKey, false), // uncompressed 65-byte key for ECIES
 64→    privateKeyHex: bytesToHex(keypair.secretKey),
 65→  };
 66→}
 67→
 68→// ---------------------------------------------------------------------------
 69→// URL construction
 70→// ---------------------------------------------------------------------------
 71→
 72→/**
 73→ * Build an invite URL with the ephemeral private key in the hash fragment.
 74→ *
 75→ * Format: `${origin}${pathname}#/invite/${token}?key=${ephemeralPrivKeyHex}`
 76→ *
 77→ * The entire path after # is the hash fragment -- never sent to server.
 78→ * React Router's HashRouter parses the route, and useSearchParams()
 79→ * provides access to the key parameter.
 80→ */
 81→export function buildInviteUrl(token: string, ephemeralPrivKeyHex: string): string {
 82→  const base = window.location.origin + window.location.pathname;
 83→  return `${base}#/invite/${token}?key=${ephemeralPrivKeyHex}`;
 84→}
 85→
 86→// ---------------------------------------------------------------------------
 87→// Create invite link
 88→// ---------------------------------------------------------------------------
 89→
 90→/**
 91→ * Create an invite link for a file or folder.
 92→ *
 93→ * 1. Generates ephemeral secp256k1 keypair
 94→ * 2. Wraps item key with ephemeral public key
 95→ * 3. Collects and wraps child keys (for folders)
 96→ * 4. Creates invite record on server
 97→ * 5. Builds URL with ephemeral private key in fragment
 98→ * 6. Zeros ephemeral private key from memory
 99→ *
100→ * @returns The invite URL and token
101→ */
102→export async function createInviteLink(params: {
103→  item: FolderChild;
104→  folderKey: Uint8Array;
105→  ipnsName: string;
106→  parentFolderId: string;
107→}): Promise<{ url: string; token: string }> {
108→  const { item, folderKey, ipnsName } = params;
109→  const ephemeralKeypair = generateEphemeralKeypair();
110→
111→  try {
112→    const vaultKeypair = useAuthStore.getState().vaultKeypair;
113→    if (!vaultKeypair) {
114→      throw new Error('Vault keypair not available');
115→    }
116→
117→    const ownerPrivateKey = vaultKeypair.privateKey;
118→    let encryptedKey: string;
119→    let encryptedChildKeys:
120→      | Array<{ keyType: 'file' | 'folder'; itemId: string; encryptedKey: string }>
121→      | undefined;
122→
123→    if (item.type === 'folder') {
124→      const folderEntry = item as FolderEntry;
125→
126→      // Unwrap the folder's own key from its ECIES-encrypted form
127→      const itemFolderKey = await unwrapKey(
128→        hexToBytes(folderEntry.folderKeyEncrypted),
129→        ownerPrivateKey
130→      );
131→
132→      try {
133→        // Wrap the folder key with ephemeral public key
134→        const wrappedForEphemeral = await wrapKey(itemFolderKey, ephemeralKeypair.publicKey);
135→        encryptedKey = bytesToHex(wrappedForEphemeral);
136→
137→        // Resolve folder metadata and collect child keys
138→        const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
139→        if (resolved) {
140→          const encryptedBytes = await fetchFromIpfs(resolved.cid);
141→          const encryptedJson = new TextDecoder().decode(encryptedBytes);
142→          const encrypted = JSON.parse(encryptedJson);
143→          const metadata = await decryptFolderMetadata(encrypted, itemFolderKey);
144→
145→          encryptedChildKeys = await collectChildKeys(
146→            metadata.children,
147→            itemFolderKey,
148→            ownerPrivateKey,
149→            ephemeralKeypair.publicKey,
150→            () => {} // No progress UI for invite creation
151→          );
152→        }
153→      } finally {
154→        itemFolderKey.fill(0);
155→      }
156→    } else {
157→      // File sharing: wrap parent folder key with ephemeral key
158→      // (recipient needs parent folder key to decrypt file metadata)
159→      const filePointer = item as FilePointer;
160→
161→      const wrappedFolderKey = await wrapKey(folderKey, ephemeralKeypair.publicKey);
162→      encryptedKey = bytesToHex(wrappedFolderKey);
163→
164→      // Resolve file metadata and wrap the file key as a child key
165→      const { metadata: fileMeta } = await resolveFileMetadata(
166→        filePointer.fileMetaIpnsName,
167→        folderKey
168→      );
169→      const fileKeyPlain = await unwrapKey(hexToBytes(fileMeta.fileKeyEncrypted), ownerPrivateKey);
170→      try {
171→        const wrappedFileKey = await wrapKey(fileKeyPlain, ephemeralKeypair.publicKey);
172→        encryptedChildKeys = [
173→          {
174→            keyType: 'file' as const,
175→            itemId: filePointer.id,
176→            encryptedKey: bytesToHex(wrappedFileKey),
177→          },
178→        ];
179→      } finally {
180→        fileKeyPlain.fill(0);
181→      }
182→    }
183→
184→    // Create invite on server
185→    const result = await shareInvitesControllerCreateInvite({
186→      itemType: item.type === 'folder' ? 'folder' : 'file',
187→      ipnsName,
188→      itemName: item.name,
189→      encryptedKey,
190→      encryptedChildKeys,
191→    });
192→
193→    // Build URL with ephemeral private key in hash fragment
194→    const url = buildInviteUrl(result.token, ephemeralKeypair.privateKeyHex);
195→
196→    return { url, token: result.token };
197→  } finally {
198→    // Zero ephemeral private key from memory
199→    ephemeralKeypair.privateKey.fill(0);
200→  }
201→}
