203→// ---------------------------------------------------------------------------
204→// Claim invite
205→// ---------------------------------------------------------------------------
206→
207→/**
208→ * Claim an invite link by unwrapping with ephemeral key and re-wrapping with own key.
209→ *
210→ * 1. Fetch full invite data from authenticated endpoint
211→ * 2. Unwrap item key with ephemeral private key
212→ * 3. Re-wrap with recipient's own public key
213→ * 4. Repeat for all child keys
214→ * 5. Zero all sensitive key material
215→ * 6. POST claim with re-wrapped keys
216→ *
217→ * @returns The share ID of the created share
218→ */
219→export async function claimInvite(
220→  token: string,
221→  ephemeralPrivKeyHex: string
222→): Promise<{ shareId: string }> {
223→  const ephemeralPrivKey = hexToBytes(ephemeralPrivKeyHex);
224→
225→  try {
226→    // Fetch full invite data (authenticated endpoint)
227→    const inviteData = await invitesControllerGetInviteData(token);
228→
229→    // Get recipient's own vault keypair
230→    const vaultKeypair = useAuthStore.getState().vaultKeypair;
231→    if (!vaultKeypair) {
232→      throw new Error('Vault keypair not available');
233→    }
234→
235→    // Unwrap item key with ephemeral private key
236→    const plaintextKey = await unwrapKey(hexToBytes(inviteData.encryptedKey), ephemeralPrivKey);
237→
238→    let reWrappedKey: string;
239→    try {
240→      // Re-wrap with recipient's own public key
241→      const wrapped = await wrapKey(plaintextKey, vaultKeypair.publicKey);
242→      reWrappedKey = bytesToHex(wrapped);
243→    } finally {
244→      plaintextKey.fill(0);
245→    }
246→
247→    // Re-wrap child keys
248→    const childKeys: Array<{
249→      keyType: 'file' | 'folder';
250→      itemId: string;
251→      encryptedKey: string;
252→    }> = [];
253→
254→    const rawChildKeys = inviteData.encryptedChildKeys;
255→
256→    if (rawChildKeys && rawChildKeys.length > 0) {
257→      for (const ck of rawChildKeys) {
258→        const plainChildKey = await unwrapKey(hexToBytes(ck.encryptedKey), ephemeralPrivKey);
259→        try {
260→          const wrappedChild = await wrapKey(plainChildKey, vaultKeypair.publicKey);
261→          childKeys.push({
262→            keyType: ck.keyType,
263→            itemId: ck.itemId,
264→            encryptedKey: bytesToHex(wrappedChild),
265→          });
266→        } finally {
267→          plainChildKey.fill(0);
268→        }
269→      }
270→    }
271→
272→    // POST claim with re-wrapped keys
273→    const result = await invitesControllerClaimInvite(token, {
274→      encryptedKey: reWrappedKey,
275→      childKeys,
276→    });
277→
278→    return { shareId: result.shareId };
279→  } finally {
280→    // Zero ephemeral private key
281→    ephemeralPrivKey.fill(0);
282→  }
283→}
