 42→/**
 43→ * Validate public key format: must be 0x04 prefix + 128 hex chars (64 bytes body = 65 bytes total uncompressed).
 44→ */
 45→function isValidPublicKey(key: string): boolean {
 46→  if (!key.startsWith('0x04')) return false;
 47→  // 0x + 130 hex chars = 65 bytes uncompressed secp256k1
 48→  const hexPart = key.slice(2);
 49→  if (hexPart.length !== 130) return false;
 50→  return /^[0-9a-fA-F]+$/.test(hexPart);
 51→}
