import { Injectable, ExecutionContext } from '@nestjs/common';
import { ThrottlerGuard } from '@nestjs/throttler';
import { timingSafeEqual } from 'node:crypto';

/**
 * Extends ThrottlerGuard with a bypass header for test environments.
 *
 * When THROTTLE_BYPASS_SECRET is set, NODE_ENV is not 'production', and
 * a request includes a matching X-Throttle-Bypass header, rate limiting
 * is skipped. This allows SDK E2E and load tests to run against staging
 * without hitting 429s.
 *
 * Security:
 *   - Production always enforces rate limits (NODE_ENV check)
 *   - If the env var is unset/empty, the header is ignored entirely
 *   - Uses crypto.timingSafeEqual to prevent timing attacks
 */
@Injectable()
export class BypassableThrottlerGuard extends ThrottlerGuard {
  async canActivate(context: ExecutionContext): Promise<boolean> {
    const secret = process.env.THROTTLE_BYPASS_SECRET;

    if (secret && process.env.NODE_ENV !== 'production') {
      const request = context.switchToHttp().getRequest();
      const rawHeader = request.headers['x-throttle-bypass'];
      const header = Array.isArray(rawHeader) ? rawHeader[0] : rawHeader;
      if (header && safeEqual(header, secret)) {
        return true;
      }
    }

    return super.canActivate(context);
  }
}

/** Constant-time string comparison using Node.js crypto. */
function safeEqual(a: string, b: string): boolean {
  const bufA = Buffer.from(a);
  const bufB = Buffer.from(b);
  if (bufA.length !== bufB.length) return false;
  return timingSafeEqual(bufA, bufB);
}

@Controller('ipns')
export class IpnsController {
  constructor(
    private readonly ipnsService: IpnsService,
    private readonly metricsService: MetricsService
  ) {}

  // [SECURITY: HIGH-04] Rate limit IPNS publish to prevent abuse
  // Each publish makes external HTTP calls to the delegated routing service
  @Throttle({ default: { limit: 10, ttl: 60000 } }) // 10 publishes per minute per user
  @Post('publish')
  @ApiOperation({
    summary: 'Publish IPNS record',
    description:
      'Relay a pre-signed IPNS record to the IPFS network via delegated routing. ' +
      'The client signs the record locally; backend relays to the delegated routing service and tracks ' +
      'the folder for TEE republishing.',
  })
  @ApiResponse({
    status: 200,
    description: 'IPNS record published successfully',
    type: PublishIpnsResponseDto,
  })
  @ApiResponse({
    status: 400,
    description: 'Bad Request - Invalid record format or missing required fields',
  })
  @ApiResponse({
    status: 401,
    description: 'Unauthorized - JWT token required',
  })
  @ApiResponse({
    status: 409,
    description:
      'Conflict - expectedSequenceNumber does not match current server sequence number. ' +
      'Response body includes currentSequenceNumber for client re-sync.',
  })
  @ApiResponse({
    status: 502,
    description: 'Bad Gateway - Failed to publish to delegated routing',
  })
  async publishRecord(
    @Request() req: RequestWithUser,
    @Body() dto: PublishIpnsDto
  ): Promise<PublishIpnsResponseDto> {
    const result = await this.ipnsService.publishRecord(req.user.id, dto);
    this.metricsService.ipnsPublishes.inc({ type: 'single' });
    return result;
  }

