+/**
+ * Load Test Client Pool
+ *
+ * Manages N CipherBoxClient instances, each with its own test account.
+ * Creates accounts in parallel, distributes workloads, and collects metrics.
+ *
+ * Reuses the shared createTestAccount/deleteTestAccount from sdk-e2e
+ * to avoid duplicating the 5-step account provisioning sequence.
+ */
+
+import { setApiClientConfig } from '@cipherbox/api-client';
+import {
+  createTestAccount,
+  deleteTestAccount,
+  type TestAccount,
+} from '../../../sdk-e2e/src/fixtures/test-harness';
+import { MetricsCollector, type OperationMetrics } from './metrics';
+import { printSummary, toJsonReport } from './reporter';
+
+const API_URL = process.env.LOAD_TEST_API_URL ?? 'http://localhost:3000';
+const SECRET = process.env.LOAD_TEST_SECRET ?? 'e2e-test-secret-do-not-use-in-production';
+
+export interface PoolClient extends TestAccount {
+  id: number;
+  metrics: MetricsCollector;
+}
+
+export interface ClientPoolOptions {
+  clientCount: number;
+  label: string;
+}
+
+/**
+ * Create a pool of N authenticated CipherBoxClient instances.
+ *
+ * Each client has its own test account, vault, and metrics collector.
+ * The api-client singleton is configured once (all clients share baseUrl,
+ * tokens are per-request via getAccessToken closure).
+ */
+export async function createClientPool(opts: ClientPoolOptions): Promise<PoolClient[]> {
+  const { clientCount, label } = opts;
+  console.log(`Creating ${clientCount} test accounts for "${label}"...`);
+  const start = performance.now();
+
+  // Create accounts in parallel batches of 5 to avoid overwhelming the API
+  const clients: PoolClient[] = [];
+  const batchSize = 5;
+
+  for (let batch = 0; batch < clientCount; batch += batchSize) {
+    const batchEnd = Math.min(batch + batchSize, clientCount);
+    const promises = [];
+
+    for (let i = batch; i < batchEnd; i++) {
+      promises.push(
+        createTestAccount({
+          apiUrl: API_URL,
+          secret: SECRET,
+          label: `${label}-${i}`,
+          emailPrefix: 'load',
+        }).then((account): PoolClient => ({ ...account, id: i, metrics: new MetricsCollector() }))
+      );
+    }
+
+    const results = await Promise.allSettled(promises);
+    for (const result of results) {
+      if (result.status === 'fulfilled') {
+        clients.push(result.value);
+      } else {
+        console.warn(`Failed to create pool client: ${result.reason}`);
+      }
+    }
+  }
+
+  // Configure the singleton once — all clients share the same baseUrl
+  // Individual tokens are injected via the getAccessToken closure on each client
+  if (clients.length > 0) {
+    const defaultHeaders = process.env.THROTTLE_BYPASS_SECRET
+      ? { 'X-Throttle-Bypass': process.env.THROTTLE_BYPASS_SECRET }
+      : undefined;
+    setApiClientConfig({
+      baseUrl: API_URL,
+      getAccessToken: async () => clients[0].accessToken,
+      defaultHeaders,
+    });
+  }","path":"tests/load/src/harness/client-pool.ts","commit_id":"5f9b7b7d749bde54453e338bd9634891709c274a","original_commit_id":"5f9b7b7d749bde54453e338bd9634891709c274a","user":{"login":"FSM1","id":12774278,"node_id":"MDQ6VXNlcjEyNzc0Mjc4","avatar_url":"https://avatars.githubusercontent.com/u/12774278?v=4","gravatar_id":"","url":"https://api.github.com/users/FSM1","html_url":"https://github.com/FSM1","followers_url":"https://api.github.com/users/FSM1/followers","following_url":"https://api.github.com/users/FSM1/following{/other_user}","gists_url":"https://api.github.com/users/FSM1/gists{/gist_id}","starred_url":"https://api.github.com/users/FSM1/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FSM1/subscriptions","organizations_url":"https://api.github.com/users/FSM1/orgs","repos_url":"https://api.github.com/users/FSM1/repos","events_url":"https://api.github.com/users/FSM1/events{/privacy}","received_events_url":"https://api.github.com/users/FSM1/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"Fixed in 35128e2. The singleton has been eliminated from client-pool entirely. Each `CipherBoxClient` now creates its own instance-scoped axios via `createAxiosInstance()`, so all clients authenticate with their own token. The `setApiClientConfig` call and import were removed.","created_at":"2026-03-22T20:57:22Z","updated_at":"2026-03-22T20:57:22Z","html_url":"https://github.com/FSM1/cipher-box/pull/318#discussion_r2972080389","pull_request_url":"https://api.github.com/repos/FSM1/cipher-box/pulls/318","_links":{"self":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2972080389"},"html":{"href":"https://github.com/FSM1/cipher-box/pull/318#discussion_r2972080389"},"pull_request":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/318"}},"reactions":{"url":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2972080389/reactions","total_count":0,"+1":0,"-1":0,"laugh":0,"hooray":0,"